+                    rcContexts = rule.requiredContexts.split(',').map(function (s) {
+                        return s.trim();
+                    }).filter(Boolean);
+                }
+                if (!rcContexts.length) {
+                    console.warn('  ⚠️  ' + key + ' rerun_cancelled_checks: rule carries no requiredContexts — skip');
+                    continue;
