+                var rcCancelled = cancelledRequiredContexts(effectiveRepoInfo, rcHead, rcContexts);
+                if (!rcCancelled.length) {
+                    console.log('  ⏭️  ' + key + ' no required context reads CANCELLED on ' +
+                                rcHead.substring(0, 7) + ' — nothing to rerun');
+                    continue;
+                }
