+                var rcHead = (ticket.pr && ticket.pr.headSha) || ticket.headSha;
+                if (!rcHead) {
+                    console.log('  ⏭️  ' + key + ' rerun_cancelled_checks: no head sha — skip');
+                    continue;
+                }
+                var rcContexts = [];
