            var top = mine[0];
            var c = top.conclusion ? String(top.conclusion).toUpperCase() : null;
            if (c === 'SUCCESS') return 'green';
            if (c === 'FAILURE' || c === 'TIMED_OUT' || c === 'CANCELLED') return 'red';
            return 'pending';
